# AvatarGroup AvatarGroup AvatarGroup это обертка для Avatar. Принимает в себя группу из avatar's. ```tsx
import React from 'react';
import { Avatar, AvatarGroup } from '@salutejs/sdds-finai';

export function App() {
    return (
        <AvatarGroup>
                {
                    Array(5).fill(true).map(() => (
                        <Avatar size="xxl" url="https://avatars.githubusercontent.com/u/1813468?v=4" />
                    ))
                }
            </AvatarGroup>
    );
}
```
